(7286264, 1135375, 13077, '<td valign="top">Cool find - if you''ve had to use multiple exposures it doesn''t show. Surprising that you could get fairly close, looks like around 135mm equivalent or maybe a little less?</td>', 'Cool find - if you''ve had to use multiple exposures it doesn''t show. Surprising that you could get fairly close, looks like around 135mm equivalent or maybe a little less?', '2014-11-19 13:28:43.000000', NULL, 1),
(7286267, 1135444, 13077, '<td valign="top">Nice and contrasty, good looking arrangement and nice tones and shapes.</td>', 'Nice and contrasty, good looking arrangement and nice tones and shapes.', '2014-11-19 13:31:49.000000', NULL, 1),
(7286268, 1135456, 13077, '<td valign="top">Good processing, I like the dreamy feel and the title.</td>', 'Good processing, I like the dreamy feel and the title.', '2014-11-19 13:32:51.000000', NULL, 1),
(7286269, 1135344, 13077, '<td valign="top">Nicely put together and full of energy.</td>', 'Nicely put together and full of energy.', '2014-11-19 13:33:12.000000', NULL, 1),
