(7286271, 1135314, 13077, '<td valign="top">Good composition, it''s attractive in a minimalist way.</td>', 'Good composition, it''s attractive in a minimalist way.', '2014-11-19 13:34:49.000000', NULL, 1),
(7286272, 1135185, 13077, '<td valign="top">Scenes of abandonment and desolation are interesting to me, but hard to photograph - you''ve done it pretty well here.</td>', 'Scenes of abandonment and desolation are interesting to me, but hard to photograph - you''ve done it pretty well here.', '2014-11-19 13:35:59.000000', NULL, 1),
(7286273, 1135112, 13077, '<td valign="top">Looks like something from the Twilight Zone.</td>', 'Looks like something from the Twilight Zone.', '2014-11-19 13:36:21.000000', NULL, 1),
(7286275, 1135419, 13077, '<td valign="top">I would definitely have recommended photoshopping out the branches at both bottom corners, but other than that it''s not a bad shot of these... (I had to look it up with the scientific name in your title) persimmons.</td>', 'I would definitely have recommended photoshopping out the branches at both bottom corners, but other than that it''s not a bad shot of these... (I had to look it up with the scientific name in your title) persimmons.', '2014-11-19 13:39:23.000000', NULL, 1),
(7286276, 1135440, 13077, '<td valign="top">Nice collection, and well arranged and lit. Well done emulating an old advertisement look.</td>', 'Nice collection, and well arranged and lit. Well done emulating an old advertisement look.', '2014-11-19 13:40:00.000000', NULL, 1),
(7286277, 1135414, 13077, '<td valign="top">I like the atmosphere of this one.</td>', 'I like the atmosphere of this one.', '2014-11-19 13:40:26.000000', NULL, 1),
(7286278, 1135412, 13077, '<td valign="top">Very nice. Well composed and perfectly exposed, and fascinating.</td>', 'Very nice. Well composed and perfectly exposed, and fascinating.', '2014-11-19 13:40:51.000000', NULL, 1),
(7286279, 1135439, 13077, '<td valign="top">Nice and bold sky and good processing. I know it would have been hard to clone out, but the power lines are quite distracting.</td>', 'Nice and bold sky and good processing. I know it would have been hard to clone out, but the power lines are quite distracting.', '2014-11-19 13:41:25.000000', NULL, 1),
(7286280, 1135160, 13077, '<td valign="top">Nice and grungy.</td>', 'Nice and grungy.', '2014-11-19 13:41:48.000000', NULL, 1),
(7286281, 1135447, 13077, '<td valign="top">I like the processing on this one, and the bit of color in the sky at the same level as the distant turbines.</td>', 'I like the processing on this one, and the bit of color in the sky at the same level as the distant turbines.', '2014-11-19 13:42:18.000000', NULL, 1),
(7286283, 1135452, 13077, '<td valign="top">Very well done, the time and effort you''ve put into it shows.</td>', 'Very well done, the time and effort you''ve put into it shows.', '2014-11-19 13:43:38.000000', NULL, 1),
(7286284, 1135307, 13077, '<td valign="top">Great details on the old books, well processed to complement them. I like the border in this case as well.</td>', 'Great details on the old books, well processed to complement them. I like the border in this case as well.', '2014-11-19 13:44:08.000000', NULL, 1),
(7286285, 1135382, 13077, '<td valign="top">Nicely done. I''m not super fond of the varying camera angles which place the bottom of the fence in different places for each frame, though. Other than that, it''s cool and it looks like it must have been a lot of work putting all the frames together.</td>', 'Nicely done. I''m not super fond of the varying camera angles which place the bottom of the fence in different places for each frame, though. Other than that, it''s cool and it looks like it must have been a lot of work putting all the frames together.', '2014-11-19 13:45:59.000000', NULL, 1),
(7286289, 1135445, 13077, '<td valign="top">I''m not very fond of this one, although it does meet the challenge.</td>', 'I''m not very fond of this one, although it does meet the challenge.', '2014-11-19 13:53:44.000000', NULL, 1),
